package com.rohit.inventory.entity;
import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="warehouse_zones") public class WarehouseZone extends BaseEntity { @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="warehouse_id",nullable=false) private Warehouse warehouse; @Column(nullable=false,length=40) private String code; @Column(nullable=false,length=120) private String name; @Column(name="zone_type",nullable=false) private String zoneType="STORAGE"; @Column(name="capacity_quantity",nullable=false) private BigDecimal capacityQuantity=BigDecimal.ZERO; @Enumerated(EnumType.STRING) @Column(nullable=false) private WarehouseStatus status=WarehouseStatus.ACTIVE; public Warehouse getWarehouse(){return warehouse;} public String getCode(){return code;} public String getName(){return name;} public String getZoneType(){return zoneType;} public BigDecimal getCapacityQuantity(){return capacityQuantity;} public WarehouseStatus getStatus(){return status;} public void setWarehouse(Warehouse v){warehouse=v;} public void setCode(String v){code=v;} public void setName(String v){name=v;} public void setZoneType(String v){zoneType=v;} public void setCapacityQuantity(BigDecimal v){capacityQuantity=v;} public void setStatus(WarehouseStatus v){status=v;} }
